def _migration_evidence(plan: dict[str, Any], current_head: str) -> dict[str, Any]:
    staging = Path(str(plan.get("staging_output") or "")).expanduser().resolve()
    blockers: list[str] = []
    staging_state: dict[str, Any] = {}
    if not staging.is_dir():
        blockers.append("staging-output-missing")
    else:
        state_path = staging / "state.json"
        if not state_path.is_file():
            blockers.append("staging-state-missing")
        else:
            try:
                staging_state = json_load(state_path)
            except Exception:
                blockers.append("staging-state-invalid")
        if staging_state.get("status") != "complete":
            blockers.append("staging-not-complete")
        staging_commit = str((staging_state.get("repository") or {}).get("commit") or "")
        if staging_commit != current_head:
            blockers.append("staging-target-commit-mismatch")
        if not (staging / ".complete").is_file():
            blockers.append("staging-complete-marker-missing")
        for relative, reason in (
            ("audit/global.json", "staging-global-audit-not-passed"),
            ("migration/audit.json", "staging-migration-audit-not-passed"),
        ):
            path = staging / relative
            try:
                passed = path.is_file() and json_load(path).get("status") == "passed"
            except Exception:
                passed = False
            if not passed:
                blockers.append(reason)
    return {
        **plan,
        "status": "ready" if not blockers else "pending",
        "target_commit": current_head,
        "staging_output": str(staging),
        "blockers": blockers,
        "cutover_performed": False,
    }

def _next_action(state: str, output: Path, repository: Path | None, head: str | None, overlay: dict[str, Any] | None, migration: dict[str, Any] | None) -> dict[str, Any]:
    if state == "current":
        return {"action": "reuse-stable-facts", "rebuild": False}
    if state == "stale-committed":
        staging = output.resolve().parent / f"{output.resolve().name}.staging-{str(head or 'unknown')[:12]}"
        return {
            "action": "create-migration-plan",
            "staging_output": str(staging),
            "command": [
                "freshness",
                "plan",
                "--out",
                str(output.resolve()),
                "--repo",
                str(repository.resolve()) if repository else "REPOSITORY",
                "--staging-out",
                str(staging),
            ],
        }
    if state == "provisional-dirty":
        return {
            "action": "commit-or-discard-worktree-overlay",
            "overlay_id": overlay.get("overlay_id") if overlay else None,
            "overlay_discard": overlay.get("discard", {}).get("command") if overlay else None,
            "git_worktree_changed_by_discard": False,
        }
    if state == "migration-pending":
        return {
            "action": "complete-isolated-staging",
            "staging_output": migration.get("staging_output") if migration else None,
            "blockers": migration.get("blockers", []) if migration else [],
        }
    if state == "migration-ready":
        return {
            "action": "review-and-cutover-explicitly",
            "staging_output": migration.get("staging_output") if migration else None,
            "automatic_cutover": False,
        }
    return {"action": "retry-freshness-check", "automatic_assumption": False}

def _last_confirmed(previous: dict[str, Any]) -> dict[str, Any] | None:
    stored = previous.get("last_confirmed")
    if isinstance(stored, dict):
        return stored
    if previous.get("state") in FRESHNESS_STATES - {"unavailable"}:
        return {
            key: previous.get(key)
            for key in ("state", "stable_state", "bound_commit", "current_head", "branch", "observed_at_utc")
        }
    return None

def _command_strings(value: Any) -> Iterator[str]:
    if isinstance(value, dict):
        preferred = {"command", "cmd", "script", "shell_command", "shellcommand", "input"}
        for key, child in value.items():
            if str(key).casefold() in preferred and isinstance(child, str):
                yield child
            elif isinstance(child, (dict, list)):
                yield from _command_strings(child)
    elif isinstance(value, list):
        for child in value:
            yield from _command_strings(child)
    elif isinstance(value, str):
        yield value

def classify_git_trigger(tool_input: Any) -> str | None:
    """Classify only successful Git actions that can change HEAD or branch."""

    for command in _command_strings(tool_input):
        match = _GIT_ACTION.search(command.strip())
        if not match:
            continue
        action = match.group(1).casefold()
        return "branch-switch" if action in {"switch", "checkout"} else action
    return None

def _read_collaboration(output: Path) -> list[dict[str, Any]]:
    path = _collaboration_path(output)
    if not path.is_file():
        return []
    records = []
    for line in path.read_text(encoding="utf-8-sig").splitlines():
        if not line.strip():
            continue
        value = json.loads(line)
        if isinstance(value, dict):
            records.append(value)
    return records[-MAX_COLLABORATION_RECORDS:]

def _relative_paths(paths: list[str] | None) -> list[str]:
    result = []
    for raw in paths or []:
        value = _bounded_text(raw, "collaboration path", 1000).replace("\\", "/").strip("/")
        if not value or value == "." or value.startswith("../") or "/../" in f"/{value}/":
            raise CkbError(f"fact freshness collaboration path must be relative: {raw}")
        result.append(value)
    return sorted(set(result))[:100]

def _feature_terms(text: str) -> set[str]:
    values = re.findall(r"[A-Za-z0-9_.-]{2,}|[\u3400-\u9fff]{2,}", text.casefold())
    terms: set[str] = set()
    for value in values:
        terms.add(value)
        if re.fullmatch(r"[\u3400-\u9fff]+", value) and len(value) > 2:
            terms.update(value[index : index + 2] for index in range(len(value) - 1))
    return terms

def git(repo: Path, *args: str, check: bool = True) -> str:
    completed = run(["git", "-C", str(repo), *args])
    if check and completed.returncode:
        message = (completed.stderr or completed.stdout).strip()
        raise CkbError(f"git {' '.join(args)} failed: {message}")
    return completed.stdout

def assert_unchanged(repository: dict[str, Any]) -> None:
    repo = Path(repository["root"])
    current = preflight(repo)
    if current["commit"] != repository["commit"] or current["tree"] != repository["tree"]:
        raise StaleSourceError(
            f"repository changed: expected {repository['commit']} / {repository['tree']}, "
            f"found {current['commit']} / {current['tree']}"
        )

def assert_source_snapshot(repository: dict[str, Any], snapshot: dict[str, Any]) -> None:
    """Verify the immutable baseline while allowing the user's HEAD/worktree to move."""
    repo = Path(repository["root"]).resolve()
    root = Path(snapshot.get("root", "")).resolve()
    if not root.is_dir():
        raise StaleSourceError(f"fixed source snapshot is missing: {root}")
    object_probe = run(["git", "-C", str(repo), "cat-file", "-e", f"{repository['commit']}^{{commit}}"], timeout=30)
    if object_probe.returncode:
        raise StaleSourceError(f"baseline commit object is unavailable: {repository['commit']}")
    head = run(["git", "-C", str(root), "rev-parse", "HEAD"], timeout=30)
    tree = run(["git", "-C", str(root), "rev-parse", "HEAD^{tree}"], timeout=30)
    status = run(["git", "-C", str(root), "status", "--porcelain=v1", "--untracked-files=no"], timeout=30)
    if head.returncode or head.stdout.strip() != repository["commit"]:
        raise StaleSourceError(f"fixed source snapshot commit drifted: {root}")
    if tree.returncode or tree.stdout.strip() != repository["tree"]:
        raise StaleSourceError(f"fixed source snapshot tree drifted: {root}")
    if status.returncode or status.stdout.strip():
        raise StaleSourceError(f"fixed source snapshot worktree drifted: {root}")

def tracked_csharp_project_files(repository: dict[str, Any]) -> list[dict[str, Any]]:
    """Return tracked C# project metadata without treating it as source entities."""
    repo = Path(repository["root"])
    commit = repository["commit"]
    raw = git(repo, "ls-tree", "-r", "-z", "--long", commit)
    result: list[dict[str, Any]] = []
    for item in raw.split("\0"):
        if not item:
            continue
        meta, path = item.split("\t", 1)
        mode, kind, blob, size_text = meta.split()
        posix = PurePosixPath(path)
        if posix.suffix.lower() not in CSHARP_PROJECT_SUFFIXES and posix.name not in CSHARP_PROJECT_NAMES:
            continue
        result.append(
            {
                "id": stable_id("project-file", commit, path, blob),
                "path": path,
                "blob": blob,
                "size": int(size_text),
                "mode": mode,
                "role": "csharp-project-metadata",
            }
        )
    return sorted(result, key=lambda value: value["path"])

def blob_bytes_many(repository: dict[str, Any], files: list[dict[str, Any]]) -> dict[str, bytes]:
    """Read a set of fixed Git blob objects through one binary cat-file session."""
    if not files:
        return {}
    repo = Path(repository["root"])
    unique_oids = list(dict.fromkeys(str(item["blob"]) for item in files))
    query = ("\n".join(unique_oids) + "\n").encode("ascii")
    completed = subprocess.run(
        ["git", "-C", str(repo), "cat-file", "--batch"],
        input=query,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        **background_process_options(),
    )
    if completed.returncode:
        raise StaleSourceError(completed.stderr.decode("utf-8", errors="replace"))
    stream = io.BytesIO(completed.stdout)
    values: dict[str, bytes] = {}
    for requested in unique_oids:
        header = stream.readline().decode("ascii", errors="replace").strip()
        parts = header.split()
        if len(parts) != 3 or parts[1] != "blob":
            raise StaleSourceError(f"Git object is unavailable or is not a blob: {requested}: {header}")
        actual, _kind, size_text = parts
        size = int(size_text)
        content = stream.read(size)
        delimiter = stream.read(1)
        if len(content) != size or delimiter != b"\n" or actual != requested:
            raise StaleSourceError(f"Git cat-file returned an invalid frame for blob: {requested}")
        values[requested] = content
    return {item["path"]: values[str(item["blob"])] for item in files}

def object_exists(repository: dict[str, Any], object_id: str) -> bool:
    completed = run(["git", "-C", repository["root"], "cat-file", "-e", object_id])
    return completed.returncode == 0

def resolve_scope_paths(all_files: list[dict[str, Any]], values: list[str]) -> set[str]:
    if not values:
        return {item["path"] for item in all_files}
    normalized: list[str] = []
    for value in values:
        path = value.replace("\\", "/").strip("/")
        if not path or path == "." or path.startswith("../") or "/../" in f"/{path}/":
            raise CkbError(f"invalid --scope-path: {value}")
        normalized.append(path)
    selected = {
        item["path"]
        for item in all_files
        if any(item["path"] == prefix or item["path"].startswith(prefix + "/") for prefix in normalized)
    }
    missing = [prefix for prefix in normalized if not any(p == prefix or p.startswith(prefix + "/") for p in selected)]
    if missing:
        raise CkbError(f"scope paths contain no supported tracked source: {missing}")
    return selected

def _canonical_json_sha256(value: Any) -> str:
    raw = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()

def _source_location(entity: dict[str, Any]) -> str:
    source_range = entity.get("range", {})
    start = int(source_range.get("start_line", 0) or 0)
    end = int(source_range.get("end_line", start) or start)
    return f"L{start}" if start == end else f"L{start}-L{end}"

def _node_label(entity: dict[str, Any]) -> str:
    if entity.get("kind") == "file":
        return str(entity.get("path", entity["id"]))
    return str(entity.get("qualified_name") or entity.get("name") or entity["id"])

def _description(entity: dict[str, Any]) -> str:
    return str(
        entity.get("meaning_zh")
        or entity.get("description_zh")
        or entity.get("role_zh")
        or ""
    )

def _confidence(link: dict[str, Any]) -> tuple[str, float, str]:
    """Map CKB provider evidence into Graphify's three deterministic tiers."""
    provider = str(link.get("provider", ""))
    relation = str(link.get("type", "references"))
    lowered = provider.lower()
    if "lexical-candidate" in lowered:
        return "INFERRED", 0.85, "deterministic lexical target resolution"
    if "ambiguous" in lowered or relation in {"possible-reference", "possible-call"}:
        return "AMBIGUOUS", 0.55, "provider marked the target ambiguous"
    return "EXTRACTED", 1.0, "AST/LSP or source-structural evidence"

def _build_networkx(nodes: list[dict[str, Any]], links: list[dict[str, Any]]):
    nx, _cluster, _labels, _scores = _networkx_modules()
    graph = nx.MultiDiGraph()
    for node in nodes:
        attrs = {key: value for key, value in node.items() if key != "id"}
        graph.add_node(node["id"], **attrs)
    for link in links:
        attrs = {key: value for key, value in link.items() if key not in {"source", "target"}}
        graph.add_edge(link["source"], link["target"], key=link["id"], **attrs)
    return graph
